export const DOUBAO_KINDS = ['text', 'image', 'video'];
const signals = ['login', 'composer', 'image', 'video', 'challenge', 'blockingDialog','rateLimited'];

export function isDoubaoPageUrl(value) {
 try {
  const url = new URL(value);
  return url.protocol === 'https:' && ['doubao.com', 'www.doubao.com'].includes(url.hostname) &&
   !url.username && !url.password && !url.port;
