import {DOUBAO_ASPECT_RATIOS} from './generation-parameters.js';
function readinessMarkup(account){
 const names={not_open:'请先打开账号后台',login_required:'需要登录',human_verification_required:'需要人工验证',rate_limited:'网站暂时限制访问',page_blocked:'需要处理弹窗',page_error:'网页检查失败',page_not_ready:'页面未就绪',not_checked:'待检查',detected_unverified:'已发现入口',not_detected:'未发现入口'};
 const capabilities=account.readiness?.capabilities||['text','image','video'].map((kind,index)=>({kind,label:['文本','图片','视频'][index],state:'not_checked'}));
 return `<div class="doubao-readiness" data-doubao-readiness><table><caption>网页能力检查 · ${account.checkedAt?'上次检查 '+h(new Date(account.checkedAt).toLocaleString()):'尚未检查'}</caption><thead><tr><th>类型</th><th>网页入口</th><th>执行器</th><th>真实生成</th><th>操作</th></tr></thead><tbody>${capabilities.map(row=>`<tr data-doubao-kind="${h(row.kind)}"><th scope="row">${h(row.label)}</th><td>${h(names[row.state]||'待检查')}</td><td>${row.adapterImplemented?'已接入':'未接通'}</td><td>${row.generationVerified?'已通过':'未验收'}</td><td><button type="button" data-doubao-verify="${h(account.id)}" data-kind="${h(row.kind)}" ${row.adapterImplemented&&account.enabled?'':'disabled'}>试用${h(row.label)}</button>${row.generationVerified?`<button type="button" data-doubao-connect="${h(account.id)}" data-kind="${h(row.kind)}">接入模型</button>`:''}</td></tr>`).join('')}</tbody></table><p class="muted">登录后自动登记插件算力；已登录账号的三类配置可直接在画布选择，首次生成无需预先试用；真实生成验收状态单独记录。网页模型与参数以账号页面为准，剩余额度未知。</p></div>`;
}
function accountMarkup(a,s,expanded=false){const loggedIn=a.loginState==='authenticated',login={authenticated:'已登录',signed_out:'未登录',unknown:'待检查登录状态'}[a.loginState]||'待检查登录状态',remove=`<button type="button" data-doubao-remove="${h(a.id)}" aria-label="删除账号空间" title="删除账号空间">×</button>`;
 if(!loggedIn)return `<section class="setting-card" data-doubao-account="${h(a.id)}"><header><strong>${h(doubaoAccountLabel(a))}</strong><span data-doubao-login-state="${h(a.loginState||'unknown')}">${login}</span>${remove}</header><p class="muted">原账号空间保留；网页未就绪不等于登录已丢失。</p><div class="setting-inline"><button type="button" data-doubao-login="${h(a.id)}" ${s.desktopAvailable?'':'disabled'}>登录</button><button type="button" data-doubao-probe="${h(a.id)}" ${s.desktopAvailable?'':'disabled'}>刷新状态</button></div></section>`;
 const kinds=a.localUsage?.kinds||{},exhausted=Object.entries(kinds).filter(([,u])=>u.exhausted).map(([k])=>({text:'文字',image:'图片',video:'视频'}[k])),status=exhausted.length?exhausted.join('、')+'用尽':Object.values(kinds).some(u=>u.needsQuotaCheck)?'待核验':a.localUsage?.usedToday?'已用':'未用';
 return `<section class="setting-card doubao-account-card" data-doubao-account="${h(a.id)}" data-doubao-login-state="authenticated"><header class="doubao-account-summary"><button type="button" data-doubao-fold="${h(a.id)}" aria-expanded="${expanded}" aria-label="${expanded?'收起':'展开'}账号详情">${expanded?'▾':'▸'}</button><strong data-doubao-account-label title="${h(doubaoAccountLabel(a))}">${h(doubaoAccountLabel(a))}</strong><span class="doubao-account-usage" title="本地使用与网页拒绝记录；具体余量以豆包页面为准">${h(status)}</span><button type="button" data-doubao-open="${h(a.id)}" ${s.desktopAvailable?'':'disabled'}>原网页</button><button type="button" data-doubao-probe="${h(a.id)}" ${s.desktopAvailable?'':'disabled'}>刷新状态</button></header><div data-doubao-details ${expanded?'':'hidden'}><div class="setting-inline"><span>${a.enabled?'参与任务调度':'已暂停调度'}</span><button type="button" role="switch" class="plugin-switch" data-doubao-toggle="${h(a.id)}" aria-label="参与新任务调度" aria-checked="${a.enabled}"><span></span></button></div><form data-doubao-edit="${h(a.id)}" class="setting-inline"><label>文字备注<input name="remark" maxlength="80" value="${h(a.remark)}" placeholder="为此账号添加备注"></label><button type="submit">保存备注</button></form><p>剩余额度以豆包页面为准</p>${readinessMarkup(a)}<div class="setting-inline"><button type="button" data-doubao-remove="${h(a.id)}">删除账号</button></div></div></section>`;}
export async function mountDoubaoSettings(target,c){
 target.classList.add('doubao-settings');
 const api=(a,b={})=>c.api('/api/official/doubao/'+a,b);
 const expandedAccounts=new Set();
 const editing=()=>target.contains(document.activeElement)&&document.activeElement.matches('input,textarea');
 let busy=false,polling=false,timer,modelSignature,renderSignature,desktopAvailable=false,passiveProbeAvailable=false,notice='';
 const showStatus=text=>{notice=text;const out=target.querySelector('[data-doubao-status]');if(out)out.textContent=text;};
 async function render({refresh=false}={}){
  const s=await api('read',refresh&&passiveProbeAvailable?{refresh:true,openIfNeeded:false}:{});if(!target.isConnected||refresh&&(busy||editing()))return;
  passiveProbeAvailable=s.passiveAccountProbe===true;
  desktopAvailable=s.desktopAvailable===true;
  // Keep controls in place between polls, especially while the pointer is
  // clicking Add/Login. Time-varying probe fields don't require a full redraw.
  const nextRender=JSON.stringify([s.settings,s.desktopAvailable,s.taskCount,s.accounts.map(a=>[a.id,a.enabled,a.loginState,a.accountName,a.remark,a.status,a.localUsage,a.readiness,a.profiles])]);
  if(nextRender===renderSignature&&target.querySelector('[data-doubao-add-form]')){clearTimeout(timer);timer=setTimeout(refreshWhenIdle,5000);return;}renderSignature=nextRender;
  const nextSignature=JSON.stringify(s.accounts.map(a=>[a.id,a.enabled,a.loginState,a.accountName,a.remark,a.profiles]));
  if(nextSignature!==modelSignature){modelSignature=nextSignature;document.dispatchEvent(new Event('shensi:model-sources-changed'));}
  target.innerHTML='<h3>豆包多开 · 网页账号空间</h3><p>用户名自动读取豆包资料；登录后可添加文字备注。</p>'+(!s.desktopAvailable?'<p role="status">登录和账号后台需要神思桌面版。</p>':'')+`<section class="setting-card"><label><input type="checkbox" data-doubao-video-questions ${s.settings?.autoConfirmVideoQuestions===true?'checked':''}> 自动处理视频生成追问</label><p class="muted">默认关闭。主动开启后，仅按最初要求确认生成参数与风格等追问，未指定的细节采用建议默认值，生成后返回原卡片；15秒要求保持不变。同一轮只发送一次，确认回执不明时保留原单等待核对。</p><label><input type="checkbox" data-doubao-auto-confirm ${s.settings?.autoConfirmGenerationParameters?'checked':''}> 自动确认图片生成参数</label><p class="muted">确认可能消耗账号额度。登录、安全验证及购买授权仍交给用户处理；不会重投旧任务。</p></section>`+s.accounts.map(a=>accountMarkup(a,s,expandedAccounts.has(a.id))).join('')+'<form data-doubao-add-form class="setting-inline"><button type="submit">新增账号空间</button></form><h4>算力接入</h4><p></p><output role="status" aria-live="polite" data-doubao-status></output>';
  const note=target.querySelector('h4');note.nextElementSibling.textContent='文本支持网页问答和显式引用，尚不执行神思 Agent 工具。图片、视频经原账号会话下载并校验后进入原卡片或文档；追问按上方自动确认设置处理。网页明确拒绝且额度耗尽时转交下一可用账号。恢复时间按该账号、该能力的网页提示记录；未公布时间时显示待核验，不推算固定24小时，也不自动重发失败任务。';
  for(const a of s.accounts){const card=[...target.querySelectorAll('[data-doubao-account]')].find(el=>el.dataset.doubaoAccount===a.id);if(a.localUsage&&card?.dataset.doubaoLoginState==='authenticated'){const p=document.createElement('p');p.className='muted';p.textContent=Object.entries(a.localUsage.kinds||{}).map(([kind,usage])=>({text:'文本',image:'图片',video:'视频'}[kind])+'：'+(usage.usedToday?'今日已使用 '+usage.todayCount+' 次':'今日未使用')+'，'+(usage.exhausted?usage.resetAt?'网页预计恢复：'+new Date(usage.resetAt).toLocaleString():'额度耗尽，网页未公布恢复时间':usage.cooldownUntil?'可重新核验，余量以网页为准':'余量未知')).join('；');card.querySelector('[data-doubao-readiness]').before(p);}}
  const recordsButton=document.createElement('button');recordsButton.type='button';recordsButton.dataset.doubaoRecords='';const taskCount=s.taskCount??s.tasks?.length??0;recordsButton.textContent='生成记录'+(taskCount?'（'+taskCount+'）':'');target.querySelector('[data-doubao-add-form]').append(recordsButton);
  if(!desktopAvailable){const message=target.querySelector('[role=status]');if(message)message.textContent='当前页面未连接桌面账号窗口：可新增空间，但无法在本页登录。请在同一资料库的神思桌面实例中打开此插件；普通浏览器新标签不会共享独立账号空间。';for(const button of target.querySelectorAll('[data-doubao-login],[data-doubao-open]')){button.disabled=false;button.dataset.doubaoDesktopHelp='';button.title='查看登录条件';}}
  showStatus(notice);clearTimeout(timer);timer=setTimeout(refreshWhenIdle,5000);
 }
 function refreshWhenIdle(){if(!target.isConnected)return;if(busy||polling||editing()){timer=setTimeout(refreshWhenIdle,5000);return;}polling=true;void render({refresh:true}).catch(error=>showStatus('状态检查失败，账号空间仍保留：'+error.message)).finally(()=>{polling=false;clearTimeout(timer);if(target.isConnected)timer=setTimeout(refreshWhenIdle,5000);});}
 async function run(button,fn,{refresh=true}={}){
  if(busy)return;busy=true;if(button)button.disabled=true;
  showStatus('正在处理…');
  try{const result=await fn();if(refresh)await render();showStatus(result?.message||'已保存');}
  catch(error){showStatus(error.message);}
  finally{busy=false;if(button?.isConnected)button.disabled=false;}
 }
 target.onchange=e=>{if(e.target.matches('[data-doubao-auto-confirm]'))void run(e.target,()=>api('settings',{autoConfirmGenerationParameters:e.target.checked}));if(e.target.matches('[data-doubao-video-questions]'))void run(e.target,()=>api('settings',{autoConfirmVideoQuestions:e.target.checked}));};
 target.onsubmit=e=>{const form=e.target;if(!form.matches('[data-doubao-add-form],[data-doubao-edit]'))return;e.preventDefault();const values=Object.fromEntries(new FormData(form));void run(e.submitter,()=>api(form.dataset.doubaoEdit?'update':'add',{...values,...form.dataset.doubaoEdit?{accountId:form.dataset.doubaoEdit}:{}}));};
 async function trial(button){
  const kind=button.dataset.kind,scope={id:c.libraryId?.(),documentId:c.current?.()?.id,nodeId:c.selectedNode?.()?.id};
  const initial=kind==='text'?'请只回复：豆包网页连接测试通过。':kind==='image'?'生成一张简洁的山水插画。':'生成一段简洁的山水风景视频。';
  const ratio=kind==='text'?'':'<label>比例（通过提示词要求）<select name="aspectRatio">'+DOUBAO_ASPECT_RATIOS.map(r=>'<option value="'+r+'">'+(r==='auto'?'网页默认':r)+'</option>').join('')+'</select></label><p>实际是否采用，以原文件尺寸为准。</p>';
  const answer=await c.modal('试用豆包'+({text:'文本',image:'图片',video:'视频'}[kind]),'<p>只提交一次网页请求，可能消耗账号额度。图片或视频结果将返回当前选中的卡片或文档。</p><textarea name="prompt" aria-label="试用要求" rows="4">'+h(initial)+'</textarea>'+ratio,[['取消','cancel'],['提交一次试用','ok']]);if(answer.value!=='ok'||!answer.prompt?.trim())return;const prompt=answer.prompt;
  if(kind!=='text'){if(!scope.id||!scope.documentId)throw Error('请先打开承载结果的文档；白板还需先选中一张普通卡片');if(c.flush&&!(await c.flush()))throw Error('请先保存当前文档');}
  await api('verify',{accountId:button.dataset.doubaoVerify,kind,prompt:String(prompt),...(kind!=='text'?{aspectRatio:answer.aspectRatio||'auto'}:{}),requestId:'trial-'+crypto.randomUUID(),...scope});await render();
 }
 target.onclick=e=>{const b=e.target.closest('button');if(!b||b.type==='submit')return;
  if(b.dataset.doubaoFold){const id=b.dataset.doubaoFold,open=!expandedAccounts.has(id);if(open)expandedAccounts.add(id);else expandedAccounts.delete(id);b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-label',(open?'收起':'展开')+'账号详情');b.textContent=open?'▾':'▸';b.closest('[data-doubao-account]').querySelector('[data-doubao-details]').hidden=!open;return;}
  if(b.hasAttribute('data-doubao-desktop-help')){void c.modal('需要桌面账号窗口','<p>账号空间没有失效。当前宿主仅提供网页预览，没有 Electron 独立账号窗口，因此不能安全隔离和持久保存豆包登录。</p><p>请从正在运行的神思桌面实例打开豆包多开，再点击这个账号的“登录”。不会通过普通浏览器混用账号，也不会重新创建或复制账号凭据。</p>',[['知道了','close']]);return;}
  if(b.hasAttribute('data-doubao-records')){openDoubaoRecords({api,modal:c.modal});return;}
  if(b.dataset.doubaoRemove){void run(b,async()=>{const answer=await c.modal('删除豆包账号','<p>停止此账号的本地等待并移入回收站，保留原任务记录与登录空间。网页中的任务可能仍在运行，请先查看原任务。</p>',[['取消','cancel'],['删除账号','remove']]);if(answer.value!=='remove')return;const result=await api('remove',{accountId:b.dataset.doubaoRemove,confirmed:true});await c.pluginsChanged?.();return result;});return;}
  if(b.dataset.doubaoVerify){void run(b,()=>trial(b));return;}
  if(b.dataset.doubaoConnect){void run(b,async()=>{await api('connect',{accountId:b.dataset.doubaoConnect,kind:b.dataset.kind});await c.pluginsChanged?.();});return;}
  const id=b.dataset.doubaoLogin||b.dataset.doubaoOpen||b.dataset.doubaoProbe||b.dataset.doubaoToggle;if(!id)return;const action=b.dataset.doubaoLogin?'login':b.dataset.doubaoOpen?'open':b.dataset.doubaoProbe?'probe':'toggle';void run(b,()=>api(action,{accountId:id,...action==='toggle'?{enabled:b.getAttribute('aria-checked')!=='true'}:{}}),{refresh:action==='probe'||action==='toggle'});};
 target.innerHTML='<h3>豆包多开 · 网页账号空间</h3><output role="status" data-doubao-status>正在读取本地账号空间…</output>';
 try{await render();}catch(error){showStatus('读取账号空间失败：'+error.message);timer=setTimeout(refreshWhenIdle,5000);}
}
